css:
/* mirrors the Slidev theme github.com/JonasTebben/jbt-theme (theme/styles/jbt.css); & = the slide */
/* faceted stage background and title band, pure CSS (no image files) */
& {
  --jbt-stage: linear-gradient(118deg, transparent 58%, rgb(255 255 255 / .07) 58% 71%, transparent 71%),
    linear-gradient(62deg, rgb(0 0 0 / .07) 22%, transparent 22% 48%, rgb(255 255 255 / .05) 48% 60%, transparent 60%),
    linear-gradient(200deg, rgb(255 255 255 / .06) 18%, transparent 18%),
    radial-gradient(60% 45% at 100% 20%, #84b5dc, transparent),
    radial-gradient(40% 35% at 100% 100%, #a3a19f, transparent),
    linear-gradient(155deg, #00aeef, #2b93cb 28%, #42789c 52%, #45505a 74%, #6c6a68);
  --jbt-band: linear-gradient(100deg, transparent 30%, rgb(255 255 255 / .06) 30% 46%, transparent 46%),
    linear-gradient(90deg, #4d7898, #5f90b4 22%, #557286 45%, #55595d 68%, #8f8d8b);
}
& { --accent: #006b96; --code-bg: #f8f8f8; --code-fg: #393a34; --code-size: 9.6px; --code-line: 12.8px; font-size: 15.2px; }
& h1 { font-size: 30px; line-height: 36px; margin-bottom: 24px; font-weight: 600; text-shadow: 0 2px 2px rgba(0, 0, 0, 0.4); }
& h2 { font-size: 30px; line-height: 36px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
& h1 + p { margin-bottom: 16px; }
& :is(p, ul, table) + h2 { margin-top: 40px; }
& ul { list-style: disc; }
& li { margin-top: 6px; margin-bottom: 6px; }
& ul ul { margin-top: 8px; list-style: circle; }
& ul ul ul { list-style: square; }
& tr { border: 0; }
& th { font-weight: 600; background: #006b96; border: 0; color: #fff; }
& td { color: #181818; background: #fff; border: 0; }
& tr:nth-child(even) td { background: #f0f0f0; }
& a { color: #006b96; }
& a:hover { color: #00b6ff; }
/* inline code stays at .9em: Slidev's `.slidev-layout :not(pre) > code` beats the theme's `li > code { .925rem }` */
& :is(pre.code, li > code, li p code, blockquote) { box-shadow: inset 0 2px 4px 0 rgb(0 0 0 / 0.05); }
& blockquote p code { box-shadow: none; }
/* Slidev sets no colour on inline code: it keeps the text colour (white in the quiz box), light weight */
& :not(pre) > code { color: inherit; font-weight: 300; }
&:is(.layout-cover, .layout-quiz, .layout-intro) :is(h1, h2) { text-align: center; }
&:is(.layout-cover, .layout-quiz) { background: linear-gradient(#0004, #0007), var(--jbt-stage); }
&:is(.layout-cover, .layout-quiz, .layout-intro) { border: 4px solid #fff; }
&:is(.layout-cover, .layout-quiz, .layout-intro) h1 { font-size: 60px; line-height: 80px; color: #fff; letter-spacing: 0.025em; text-shadow: 2px 2px rgba(0, 0, 0, 0.2); }
&:is(.layout-cover, .layout-quiz, .layout-intro) h2 { color: #e1f7ff; letter-spacing: 0.025em; text-shadow: 2px 2px rgba(0, 0, 0, 0.2); }
&.layout-quiz { background-blend-mode: lighten; text-shadow: 1px 1px rgba(0, 0, 0, 0.4); }
&.layout-quiz h1 { font-size: 36px; line-height: 40px; }
/* the answer box: `.slidev-layout.quiz > div > div` in the theme */
&.layout-quiz :is(.center-wrap > div, .el > .content > div) { margin-top: 16px; color: #fff; padding: 16px 32px; background-color: rgba(0, 0, 0, 0.2); border-radius: 8px; box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1); }
&.layout-quiz :is(.center-wrap > div, .el > .content > div) code { background-color: #00b6ff66; font-weight: 600; }
&.layout-quiz :is(.center-wrap > div, .el > .content > div) ul { list-style: none; }
&.layout-quiz :is(.center-wrap > div, .el > .content > div) li { background-color: color-mix(in srgb, #006b96 65%, #00b6ff 5%); border-radius: 0.375rem; padding: 0.5rem; }
&:is(.layout-default, .layout-hands-on) { background: #fff; background-image: var(--jbt-band); background-size: 100% 85px; background-repeat: no-repeat; }
&:is(.layout-default, .layout-hands-on) h1 { color: #fff; }
&.layout-hands-on h1 { text-transform: uppercase; }
&.layout-hands-on h1::before { content: '💻'; color: #e1f7ff; margin-right: 0.3em; }
&.layout-intro { background: var(--jbt-stage); }
&.layout-fact { text-align: center; }
&.layout-fact h1 { font-size: 96px; line-height: 1; font-weight: 700; }
&.layout-fact h1 + p { font-size: 24px; line-height: 32px; font-weight: 700; }
&.layout-statement { text-align: center; }
&.layout-statement h1 { font-size: 60px; line-height: 1; font-weight: 700; }
&.layout-section h1 { font-size: 60px; font-weight: 500; line-height: 80px; }
& h1 { overflow-wrap: break-word; }
&:is(.layout-cover, .layout-intro) .pageno { display: none; }
/* a colour chosen for the whole box beats the theme's heading/paragraph colours */
.slide .el.colored > .content :is(h1, h2, h3, h4, h5, h6, p, li, blockquote, strong, em) { color: inherit; }
